public struct ReaderAnchor {
    public var chapterIndex: UInt32
    public var blockIndex: UInt32
    public var characterOffset: UInt32
    public var chapterRatio: Double

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(chapterIndex: UInt32, blockIndex: UInt32, characterOffset: UInt32, chapterRatio: Double) {
        self.chapterIndex = chapterIndex
        self.blockIndex = blockIndex
        self.characterOffset = characterOffset
        self.chapterRatio = chapterRatio
    }
}



extension ReaderAnchor: Equatable, Hashable {
    public static func ==(lhs: ReaderAnchor, rhs: ReaderAnchor) -> Bool {
        if lhs.chapterIndex != rhs.chapterIndex {
            return false
        }
        if lhs.blockIndex != rhs.blockIndex {
            return false
        }
        if lhs.characterOffset != rhs.characterOffset {
            return false
        }
        if lhs.chapterRatio != rhs.chapterRatio {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(chapterIndex)
        hasher.combine(blockIndex)
        hasher.combine(characterOffset)
        hasher.combine(chapterRatio)
    }
}


