#endif
fileprivate struct FfiConverterSequenceTypeReaderAnnotation: FfiConverterRustBuffer {
    typealias SwiftType = [ReaderAnnotation]

    public static func write(_ value: [ReaderAnnotation], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeReaderAnnotation.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [ReaderAnnotation] {
        let len: Int32 = try readInt(&buf)
        var seq = [ReaderAnnotation]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeReaderAnnotation.read(from: &buf))
        }
        return seq
    }
}

